public record UsuarioPerfil(
        Long iduser,
        String deslogin,
        String desperson
) {
    public static UsuarioPerfil of(Usuario user, Person person) {
        return new UsuarioPerfil(
                user.getIduser(),
                user.getDeslogin(),
                person != null ? person.getDesperson() : null);
    }
}

async function carregarAulas() {
  try {
    const resposta = await fetch('/aulas');
    if (!resposta.ok) {
      throw new Error('HTTP ' + resposta.status);
    }
    return await resposta.json();
  } catch (erro) {
    console.error('falha ao carregar aulas', erro);
    return [];
  }
}
